ROOT = Path(__file__).resolve().parents[2]
SCRIPT = ROOT / "scripts" / "generate-repository-delete-password.py"
ITERATIONS = 600_000
PTY_AVAILABLE = os.name == "posix" and pty is not None and termios is not None
VERIFIER_PATTERN = re.compile(
    rb"\{pbkdf2-sha256\}(\d+):([A-Za-z0-9+/]+={0,2}):([A-Za-z0-9+/]+={0,2})\n?\Z"
)


def invoke(*arguments: str, input_bytes: bytes = b"") -> subprocess.CompletedProcess[bytes]:
    return subprocess.run(
        [sys.executable, str(SCRIPT), *arguments],
        input=input_bytes,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        cwd=ROOT,
        check=False,
        start_new_session=(os.name != "nt"),
    )


def parse_verifier(stdout: bytes) -> tuple[int, bytes, bytes]:
    match = VERIFIER_PATTERN.fullmatch(stdout)
    if match is None:
        raise AssertionError(f"stdout was not exactly one verifier: {stdout!r}")

    iterations = int(match.group(1))
    salt_text = match.group(2)
    hash_text = match.group(3)
    salt = base64.b64decode(salt_text, validate=True)
    derived_hash = base64.b64decode(hash_text, validate=True)
    if base64.b64encode(salt) != salt_text or base64.b64encode(derived_hash) != hash_text:
        raise AssertionError("verifier base64 fields were not canonical and padded")
    if len(salt) != 16:
        raise AssertionError(f"salt length was {len(salt)}, expected 16")
    if len(derived_hash) != 32:
        raise AssertionError(f"derived hash length was {len(derived_hash)}, expected 32")
    return iterations, salt, derived_hash


def assert_matches_password(
    test: unittest.TestCase,
    stdout: bytes,
    password: str,
    expected_iterations: int = ITERATIONS,
) -> tuple[bytes, bytes]:
    iterations, salt, derived_hash = parse_verifier(stdout)
    test.assertEqual(iterations, expected_iterations)
    independently_derived = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt, iterations, dklen=32
    )
    test.assertEqual(derived_hash, independently_derived)
    return salt, derived_hash


def load_generator_module():
    spec = importlib.util.spec_from_file_location("repository_delete_password_generator", SCRIPT)
    if spec is None or spec.loader is None:
        raise AssertionError("could not load the password generator module")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class RepositoryDeletePasswordGeneratorTest(unittest.TestCase):
    def test_stdin_mode_emits_canonical_verifier_for_exact_utf8_bytes(self) -> None:
        password = "  å秘密🔒\0\t\n"
        result = invoke("--password-stdin", input_bytes=password.encode("utf-8"))

        self.assertEqual(result.returncode, 0, result.stderr.decode("utf-8", "replace"))
        assert_matches_password(self, result.stdout, password)
        self.assertEqual(result.stderr, b"")
        self.assertNotIn(password.encode("utf-8"), result.stdout)
        self.assertNotIn(password.encode("utf-8"), result.stderr)

