class InteractiveResult:
    def __init__(
        self,
        returncode: int,
        stdout: bytes,
        stderr: bytes,
        terminal: bytes,
        echo_disabled: tuple[bool, ...],
    ):
        self.returncode = returncode
        self.stdout = stdout
        self.stderr = stderr
        self.terminal = terminal
        self.echo_disabled = echo_disabled


class InteractiveSession:
    def __init__(self, pid: int, terminal_fd: int, stdout_fd: int, stderr_fd: int):
        self.pid = pid
        self.terminal_fd = terminal_fd
        self.stdout_fd = stdout_fd
        self.stderr_fd = stderr_fd
        self.stdout = bytearray()
        self.stderr = bytearray()
        self.terminal = bytearray()
        self.echo_disabled: list[bool] = []

    def read_until_prompt(self, prompt: bytes) -> None:
        deadline = time.monotonic() + 8
        while prompt not in self.stderr:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise AssertionError(f"interactive prompt not received: {bytes(self.stderr)!r}")
            readable, _, _ = select.select([self.terminal_fd, self.stderr_fd], [], [], remaining)
            if not readable:
                continue
            for fd in readable:
                try:
                    chunk = os.read(fd, 4096)
                except OSError as exc:
                    if fd == self.terminal_fd and exc.errno == errno.EIO:
                        raise AssertionError(
                            f"interactive terminal closed before prompt: {bytes(self.terminal)!r}"
                        ) from None
                    raise
                if not chunk:
                    if fd == self.stderr_fd:
                        raise AssertionError(
                            f"interactive stderr closed before prompt: {bytes(self.stderr)!r}"
                        )
                    raise AssertionError(
                        f"interactive terminal closed before prompt: {bytes(self.terminal)!r}"
                    )
                (self.stderr if fd == self.stderr_fd else self.terminal).extend(chunk)

    def finish(self) -> InteractiveResult:
        open_fds = {
            self.terminal_fd: self.terminal,
            self.stdout_fd: self.stdout,
            self.stderr_fd: self.stderr,
        }
        deadline = time.monotonic() + 10
        child_status: int | None = None
        try:
            while child_status is None or open_fds:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise AssertionError(
                        "interactive generator did not exit cleanly; "
                        f"stdout={bytes(self.stdout)!r} stderr={bytes(self.stderr)!r} "
                        f"terminal={bytes(self.terminal)!r}"
                    )
                readable, _, _ = select.select(list(open_fds), [], [], remaining)
                for fd in readable:
                    try:
                        chunk = os.read(fd, 4096)
                    except OSError as exc:
                        if fd == self.terminal_fd and exc.errno == errno.EIO:
                            chunk = b""
                        else:
                            raise
                    if chunk:
                        open_fds[fd].extend(chunk)
                    else:
                        os.close(fd)
                        del open_fds[fd]
                if child_status is None:
                    finished_pid, status = os.waitpid(self.pid, os.WNOHANG)
                    if finished_pid:
                        child_status = status
            return InteractiveResult(
                os.waitstatus_to_exitcode(child_status),
                bytes(self.stdout),
                bytes(self.stderr),
                bytes(self.terminal),
                tuple(self.echo_disabled),
            )
        except BaseException:
            self.terminate()
            raise
        finally:
            for fd in open_fds:
                try:
                    os.close(fd)
                except OSError:
                    pass

    def terminate(self) -> None:
        try:
            finished_pid, _ = os.waitpid(self.pid, os.WNOHANG)
        except ChildProcessError:
            return
        if finished_pid:
            return
        try:
            os.kill(self.pid, signal.SIGKILL)
        except ProcessLookupError:
            return
        try:
            os.waitpid(self.pid, 0)
        except ChildProcessError:
            pass

    def close(self) -> None:
        self.terminate()
        for fd in (self.terminal_fd, self.stdout_fd, self.stderr_fd):
            try:
                os.close(fd)
            except OSError:
                pass


def start_interactive(arguments: tuple[str, ...] = ()) -> InteractiveSession:
    if not PTY_AVAILABLE:
        raise unittest.SkipTest("POSIX pseudo-terminal support is unavailable")
    stdout_read, stdout_write = os.pipe()
    stderr_read, stderr_write = os.pipe()
    pid, terminal_fd = pty.fork()
    if pid == 0:
        os.close(stdout_read)
        os.close(stderr_read)
        os.dup2(stdout_write, 1)
        os.dup2(stderr_write, 2)
        os.close(stdout_write)
        os.close(stderr_write)
        os.execv(sys.executable, [sys.executable, str(SCRIPT), *arguments])

    os.close(stdout_write)
    os.close(stderr_write)
    return InteractiveSession(pid, terminal_fd, stdout_read, stderr_read)


def run_interactive_arguments(arguments: tuple[str, ...]) -> InteractiveResult:
    session = start_interactive(arguments)
    return session.finish()


def run_interactive(passwords: tuple[str, ...]) -> InteractiveResult:
    session = start_interactive()
    try:
        prompts = (b"Password: ", b"Confirm password: ")
        for index, password in enumerate(passwords):
            session.read_until_prompt(prompts[index])
            terminal_flags = termios.tcgetattr(session.terminal_fd)[3]
            session.echo_disabled.append(not (terminal_flags & termios.ECHO))
            if terminal_flags & termios.ECHO:
                raise AssertionError(f"terminal input echo remained enabled for prompt {index + 1}")
            os.write(session.terminal_fd, password.encode("utf-8") + b"\n")
    except BaseException:
        session.close()
        raise
    return session.finish()


def run_interactive_eof() -> InteractiveResult:
    session = start_interactive()
    try:
        session.read_until_prompt(b"Password: ")
        os.write(session.terminal_fd, b"\x04")
    except BaseException:
        session.close()
        raise
    return session.finish()


def run_interactive_interrupt() -> InteractiveResult:
    session = start_interactive()
    try:
        session.read_until_prompt(b"Password: ")
        os.kill(session.pid, signal.SIGINT)
    except BaseException:
        session.close()
        raise
    return session.finish()


